import React from "react";
import {Card, type PiCardProps} from "@pihanga2/core";

import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
} from "./dropdown-menu.ui";

import type {
  DropDownMenuEntry,
  DropDownMenuEvents,
  DropDownMenuProps,
  MenuContent,
  MenuLabelEntry,
  MenuSubMenuEntry,
} from "./drop-down.types";

import {DropdownOpenContext} from "./dropdown-context";

export const Component = (
  props: PiCardProps<DropDownMenuProps, DropDownMenuEvents>,
): React.ReactNode => {
  const {trigger, menuLabel, menuAlign, items, cardName, checkboxCloseDelayMs} =
    props;

  const [open, setOpen] = React.useState(false);
  const closeTimerRef = React.useRef<number | null>(null);

  const [localCheckboxChecked, setLocalCheckboxChecked] = React.useState<
    Record<string, boolean>
  >({});

  const checkboxKey = React.useCallback((path: string[], id: string) => {
    return [...path, id].join("::");
  }, []);

  const buildCheckboxStateFromItems = React.useCallback(
    (
      entries: DropDownMenuEntry[] | undefined,
      path: string[] = [],
    ): Record<string, boolean> => {
      const state: Record<string, boolean> = {};
      if (!entries?.length) return state;

      for (const entry of entries) {
        if (!entry || typeof entry === "string") continue;
        if (entry.type === "group") {
          Object.assign(state, buildCheckboxStateFromItems(entry.items, path));
          continue;
        }
        if (entry.type === "submenu") {
          const subId = entryIdForPath(entry);
          Object.assign(
            state,
            buildCheckboxStateFromItems(entry.items, [...path, subId]),
          );
          continue;
        }
        if (entry.type === "checkbox") {
          const initial = Boolean(
            entry.checked ?? entry.defaultChecked ?? false,
          );
          state[checkboxKey(path, entry.id)] = initial;
        }
      }

      return state;
    },
    [checkboxKey],
  );

  function clearCloseTimer() {
    if (closeTimerRef.current !== null) {
      window.clearTimeout(closeTimerRef.current);
      closeTimerRef.current = null;
    }
  }

  function closeNow() {
    clearCloseTimer();
    setOpen(false);
  }

  function scheduleClose(delayMs: number) {
    clearCloseTimer();
    closeTimerRef.current = window.setTimeout(() => {
      closeTimerRef.current = null;
      setOpen(false);
    }, delayMs);
  }

  React.useEffect(() => {
    return () => {
      // cleanup on unmount
      clearCloseTimer();
    };
  }, []);

  // If the menu model changes while open, resync the local checkbox state.
  // This lets external state updates still win.
  React.useEffect(() => {
    if (!open) return;
    setLocalCheckboxChecked(buildCheckboxStateFromItems(items));
  }, [open, items, buildCheckboxStateFromItems]);

  function renderTrigger() {
    // IMPORTANT: Radix `DropdownMenuTrigger` with `asChild` requires its direct
    // child to accept/forward the props Radix injects (pointer handlers, aria
    // attributes, refs). `@pihanga2/core`'s <Card /> does not forward arbitrary
    // props to the underlying DOM element rendered by the referenced card.
    //
    // So we always provide a real DOM element as the trigger and render the
    // PiCard inside it. Events bubble, so clicking the inner PiButton still
    // toggles the menu.
    //
    // We provide the dropdown's open state via context so nested components
    // (like Button) can hide their tooltips when the dropdown is open.
    return (
      <span className="inline-flex" data-pihanga-trigger-wrapper>
        <DropdownOpenContext.Provider value={open}>
          <Card cardName={trigger} parentCard={cardName} />
        </DropdownOpenContext.Provider>
      </span>
    );
  }

  function renderLabel() {
    if (!menuLabel) return null;
    return (
      <>
        <DropdownMenuLabel>{menuLabel}</DropdownMenuLabel>
        <DropdownMenuSeparator />
      </>
    );
  }

  function contentToNode(content: MenuContent): React.ReactNode {
    if (typeof content === "string") return content;
    return <Card cardName={content} parentCard={cardName} />;
  }

  function entryIdForPath(entry: MenuSubMenuEntry): string {
    if (entry.id) return entry.id;
    return typeof entry.label === "string" ? entry.label : "submenu";
  }

  function emitSelected(ev: {
    type: "item" | "checkbox" | "radio";
    id: string;
    value?: string;
    checked?: boolean;
    path?: string[];
  }) {
    props.onSelected(ev);
  }

  function renderShortcut(shortcut?: string) {
    if (!shortcut) return null;
    return <DropdownMenuShortcut>{shortcut}</DropdownMenuShortcut>;
  }

  function renderEntries(entries: DropDownMenuEntry[], path: string[] = []) {
    return entries.map((entry, idx) => {
      if (entry === null) {
        return <DropdownMenuSeparator key={`sep-${idx}`} />;
      }

      if (typeof entry === "string") {
        // legacy style within `items` (still supported)
        return (
          <DropdownMenuItem
            key={`s-${idx}`}
            onSelect={() => emitSelected({type: "item", id: entry, path})}
          >
            {entry}
          </DropdownMenuItem>
        );
      }

      if (entry.type === "separator") {
        return <DropdownMenuSeparator key={`sepobj-${idx}`} />;
      }

      if (entry.type === "label") {
        const e: MenuLabelEntry = entry;
        return (
          <DropdownMenuLabel key={`label-${idx}`} inset={e.inset}>
            {contentToNode(e.label)}
          </DropdownMenuLabel>
        );
      }

      if (entry.type === "group") {
        const e = entry;
        return (
          <DropdownMenuGroup key={`group-${idx}`}>
            {e.label && (
              <DropdownMenuLabel inset={e.inset}>
                {contentToNode(e.label)}
              </DropdownMenuLabel>
            )}
            {renderEntries(e.items, path)}
          </DropdownMenuGroup>
        );
      }

      if (entry.type === "submenu") {
        const e: MenuSubMenuEntry = entry;
        const subId = entryIdForPath(e);
        const nextPath = [...path, subId];
        return (
          <DropdownMenuSub key={`sub-${idx}`}>
            <DropdownMenuSubTrigger inset={e.inset} disabled={e.disabled}>
              {contentToNode(e.label)}
              {renderShortcut(e.shortcut)}
            </DropdownMenuSubTrigger>
            <DropdownMenuSubContent>
              {renderEntries(e.items, nextPath)}
            </DropdownMenuSubContent>
          </DropdownMenuSub>
        );
      }

      if (entry.type === "checkbox") {
        const e = entry;
        const key = checkboxKey(path, e.id);
        const checked =
          localCheckboxChecked[key] ??
          Boolean(e.checked ?? e.defaultChecked ?? false);
        return (
          <DropdownMenuCheckboxItem
            key={`cb-${e.id}`}
            checked={checked}
            disabled={e.disabled}
            onCheckedChange={(checked) => {
              const nextChecked = Boolean(checked);

              // Update local state immediately so the tick updates while menu is open.
              setLocalCheckboxChecked((prev) => ({
                ...prev,
                [key]: nextChecked,
              }));

              emitSelected({
                type: "checkbox",
                id: e.id,
                checked: nextChecked,
                path,
              });

              // If a delay is configured, keep menu open but schedule an auto-close.
              // Each checkbox selection resets the timer.
              if (typeof checkboxCloseDelayMs === "number") {
                if (checkboxCloseDelayMs > 0) {
                  scheduleClose(checkboxCloseDelayMs);
                } else {
                  // Treat 0ms as "close immediately".
                  closeNow();
                }
              }
            }}
            onSelect={(evt) => {
              // keepOpen OR delayed-close mode should keep menu open after select.
              if (e.keepOpen || typeof checkboxCloseDelayMs === "number") {
                evt.preventDefault();
              }
            }}
          >
            {contentToNode(e.label)}
            {renderShortcut(e.shortcut)}
          </DropdownMenuCheckboxItem>
        );
      }

      if (entry.type === "radio-group") {
        const e = entry;
        return (
          <DropdownMenuRadioGroup
            key={`rg-${e.id}`}
            value={e.value}
            defaultValue={e.defaultValue}
            onValueChange={(value) => {
              emitSelected({type: "radio", id: e.id, value, path});
            }}
          >
            {e.label && (
              <DropdownMenuLabel inset={e.inset}>
                {contentToNode(e.label)}
              </DropdownMenuLabel>
            )}
            {e.items.map((ri) => (
              <DropdownMenuRadioItem
                key={`${e.id}:${ri.value}`}
                value={ri.value}
                disabled={ri.disabled}
                className={ri.inset ? "pl-8" : undefined}
                hideIcon={ri.hideIcon}
                onSelect={(evt) => {
                  if (ri.keepOpen) evt.preventDefault();
                }}
              >
                {contentToNode(ri.label)}
                {renderShortcut(ri.shortcut)}
              </DropdownMenuRadioItem>
            ))}
          </DropdownMenuRadioGroup>
        );
      }

      if (entry.type === "item") {
        const e = entry;
        return (
          <DropdownMenuItem
            key={`it-${e.id}`}
            disabled={e.disabled}
            className={e.inset ? "pl-8" : undefined}
            onSelect={(evt) => {
              if (e.keepOpen) evt.preventDefault();
              emitSelected({type: "item", id: e.id, path});
            }}
          >
            {contentToNode(e.label)}
            {renderShortcut(e.shortcut)}
          </DropdownMenuItem>
        );
      }

      // Exhaustiveness guard (should never happen)
      return null;
    });
  }

  const effectiveItems = items;

  return (
    <DropdownMenu
      data-pihanga={cardName}
      open={open}
      onOpenChange={(nextOpen) => {
        // Any non-checkbox close reason (outside click, escape, blur, etc.)
        // should close immediately and cancel pending timers.
        if (!nextOpen) {
          closeNow();
          return;
        }

        clearCloseTimer();
        setLocalCheckboxChecked(buildCheckboxStateFromItems(items));
        setOpen(true);
      }}
    >
      <DropdownMenuTrigger asChild>{renderTrigger()}</DropdownMenuTrigger>
      <DropdownMenuContent align={menuAlign}>
        {renderLabel()}
        {effectiveItems?.length ? renderEntries(effectiveItems) : null}
      </DropdownMenuContent>
    </DropdownMenu>
  );
};

import {
  createCardDeclaration,
  createOnAction,
  type PiCardRef,
  registerActions,
} from "@pihanga2/core";

export const DROP_DOWN_MENU_CARD = "pi/drop-down-menu";
export const DropDownMenu = createCardDeclaration<
  DropDownMenuProps,
  DropDownMenuEvents
>(DROP_DOWN_MENU_CARD);

export const DROP_DOWN_MENU_ACTION = registerActions(DROP_DOWN_MENU_CARD, [
  "selected",
]);

export const onDropDownMenuClicked = createOnAction<DropDownMenuSelectedEvent>(
  DROP_DOWN_MENU_ACTION.SELECTED,
);

export type DropDownMenuProps = {
  /**
   * Dropdown trigger.
   *
   * - For a PiButton (or any custom) trigger, pass a `PiCardRef` and use the
   *   referenced card's props. For `PiButton` specifically:
   *   - `opts.iconName` + `opts.iconPlacement` to show an icon on the left/right.
   *   - `label: ""` for an icon-only button.
   *
   * Implementation note: the dropdown trigger is wrapped in a DOM element so
   * Radix can attach trigger handlers even when the trigger is rendered via
   * `@pihanga2/core`'s `<Card />`.
   */
  trigger: PiCardRef;
  menuAlign?: "center" | "end" | "start";
  menuLabel?: string;

  /**
   * Menu declaration (supports sub-menus, checkbox/radio items, groups, labels, separators, ...).
   *
   * Prefer this over `itemGroups`.
   */
  items?: DropDownMenuEntry[];

  /**
   * When set (ms), selecting a checkbox item will keep the menu open and auto-close
   * it after this delay. Each checkbox selection resets the timer.
   *
   * Blur / outside interactions still close immediately.
   */
  checkboxCloseDelayMs?: number;

  className?: string;
};

/**
 * Menu content can either be plain text or an embedded PiCard.
 *
 * NOTE: we intentionally type this as `PiCardRef` (a string), not a card definition.
 */
export type MenuContent = string | PiCardRef;

export type MenuSeparatorEntry = null | {type: "separator"};

export type MenuLabelEntry = {
  type: "label";
  label: MenuContent;
  inset?: boolean;
};

export type MenuActionItemEntry = {
  type: "item";
  id: string;
  label: MenuContent;
  disabled?: boolean;
  inset?: boolean;
  shortcut?: string;
  /** Prevents the dropdown from closing when selected. */
  keepOpen?: boolean;
};

export type MenuCheckboxItemEntry = {
  type: "checkbox";
  id: string;
  label: MenuContent;
  disabled?: boolean;
  inset?: boolean;
  shortcut?: string;
  checked?: boolean;
  defaultChecked?: boolean;
  /** Prevents the dropdown from closing when selected. */
  keepOpen?: boolean;
};

export type MenuRadioItemEntry = {
  value: string;
  label: MenuContent;
  disabled?: boolean;
  inset?: boolean;
  shortcut?: string;
  /** Prevents the dropdown from closing when selected. */
  keepOpen?: boolean;
  /** Only affects the icon rendering (registry/ui supports this). */
  hideIcon?: boolean;
};

export type MenuRadioGroupEntry = {
  type: "radio-group";
  id: string;
  label?: MenuContent;
  /** Optional extra left padding for the label (matches shadcn dropdown label inset). */
  inset?: boolean;
  value?: string;
  defaultValue?: string;
  items: MenuRadioItemEntry[];
};

export type MenuGroupEntry = {
  type: "group";
  label?: MenuContent;
  /** Optional extra left padding for the label (matches shadcn dropdown label inset). */
  inset?: boolean;
  items: DropDownMenuEntry[];
};

export type MenuSubMenuEntry = {
  type: "submenu";
  /** Optional id used for event `path` (falls back to label string if possible). */
  id?: string;
  label: MenuContent;
  disabled?: boolean;
  inset?: boolean;
  shortcut?: string;
  items: DropDownMenuEntry[];
};

export type DropDownMenuEntry =
  | string
  | MenuSeparatorEntry
  | MenuLabelEntry
  | MenuActionItemEntry
  | MenuCheckboxItemEntry
  | MenuRadioGroupEntry
  | MenuGroupEntry
  | MenuSubMenuEntry;

export type DropDownMenuSelectedEventAdvanced = {
  /** Discriminant for advanced menu items. */
  type: "item" | "checkbox" | "radio";

  /** The id of the selected menu entry (or the radio group id for `type: 'radio'`). */
  id: string;

  /** For radio items this is the selected value. */
  value?: string;

  /** For checkbox items this is the new checked state. */
  checked?: boolean;

  /** Hierarchical path of submenu ids leading to the item (if any). */
  path?: string[];
};

export type DropDownMenuSelectedEvent = DropDownMenuSelectedEventAdvanced;

export type DropDownMenuEvents = {
  onSelected: DropDownMenuSelectedEvent;
};

import React from "react";

/**
 * Context to communicate dropdown menu state to nested components (e.g., Button triggers).
 * This allows triggers to hide their tooltips when the dropdown is open.
 */
export const DropdownOpenContext = React.createContext<boolean>(false);

export const useDropdownOpen = () => React.useContext(DropdownOpenContext);

"use client";

import * as React from "react";

import * as DropdownMenuPrimitive from "@radix-ui/react-dropdown-menu";
import {type VariantProps, cva} from "class-variance-authority";
import {CheckIcon, ChevronRightIcon} from "lucide-react";

import {cn} from "@/lib/utils";

/**
 * Pihanga-owned copy of the registry dropdown-menu primitives.
 *
 * Why this exists:
 * - `src/registry/**` is upstream-managed and must remain read-only.
 * - We needed menu width/shrink-to-fit fixes (`w-max`, avoid %/calc widths)
 *   for correct sizing with long labels.
 */
export const dropdownMenuItemVariants = cva(
  cn(
    "relative flex cursor-pointer items-center gap-2 rounded-md align-middle text-sm no-focus-ring transition-bg-ease select-none data-disabled:pointer-events-none data-disabled:opacity-50",
    "[&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0 [&_svg]:text-subtle-foreground",
    "text-accent-foreground hover:bg-accent focus:bg-accent focus:text-accent-foreground",
  ),
  {
    defaultVariants: {
      size: "default",
      variant: "default",
    },
    variants: {
      size: {
        // NOTE: Do NOT use %/calc-based widths here.
        // Radix positions the dropdown content with a shrink-to-fit layout.
        // If menu items have percentage widths, they don't contribute to the
        // intrinsic (max-content) sizing of the container.
        default: "mx-1 h-[28px] px-2.5",
        none: "",
      },
      variant: {
        default: "focus:bg-accent focus:text-accent-foreground",
        none: "",
      },
    },
  },
);

const dropdownMenuLabelVariants = cva(
  cn(
    "mt-1.5 mb-2 cursor-default px-[14px] text-xs font-medium text-muted-foreground select-none",
  ),
  {
    variants: {
      inset: {
        true: "pl-8",
      },
    },
  },
);

export function DropdownMenu(props: DropdownMenuPrimitive.DropdownMenuProps) {
  return <DropdownMenuPrimitive.Root {...props} />;
}

export function DropdownMenuTrigger(
  props: DropdownMenuPrimitive.DropdownMenuTriggerProps,
) {
  return <DropdownMenuPrimitive.Trigger {...props} />;
}

export function DropdownMenuGroup(
  props: DropdownMenuPrimitive.DropdownMenuGroupProps,
) {
  return <DropdownMenuPrimitive.Group className="py-1.5" {...props} />;
}

export function DropdownMenuPortal(
  props: DropdownMenuPrimitive.DropdownMenuPortalProps,
) {
  return <DropdownMenuPrimitive.Portal {...props} />;
}

export function DropdownMenuSub(
  props: DropdownMenuPrimitive.DropdownMenuSubProps,
) {
  return <DropdownMenuPrimitive.Sub {...props} />;
}

export function DropdownMenuRadioGroup(
  props: DropdownMenuPrimitive.DropdownMenuRadioGroupProps,
) {
  return <DropdownMenuPrimitive.RadioGroup {...props} />;
}

export function DropdownMenuSubTrigger({
  children,
  className,
  inset,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.SubTrigger> & {
  inset?: boolean;
}) {
  return (
    <DropdownMenuPrimitive.SubTrigger
      className={cn(
        "mx-1 flex cursor-default items-center gap-2 rounded-md px-2 py-1.5 text-sm outline-hidden select-none focus:bg-accent data-[state=open]:bg-accent",
        "no-focus-ring",
        "data-disabled:pointer-events-none data-disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
        inset && "pl-8",
        className,
      )}
      {...props}
    >
      {children}
      <ChevronRightIcon className="ml-auto" />
    </DropdownMenuPrimitive.SubTrigger>
  );
}

export function DropdownMenuSubContent({
  className,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.SubContent>) {
  return (
    <DropdownMenuPrimitive.SubContent
      className={cn(
        // `w-max` ensures submenu width grows with its content (up to max-w)
        "z-50 max-w-[100vw] min-w-32 w-max overflow-hidden rounded-lg bg-popover p-1 text-popover-foreground shadow-floating data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95",
        className,
      )}
      {...props}
    />
  );
}

export function DropdownMenuContent({
  className,
  portal,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Content> & {
  portal?: boolean;
}) {
  const content = (
    <DropdownMenuPrimitive.Content
      className={cn(
        // `w-max` makes the menu container grow with its content (up to max-w)
        "z-50 max-w-[100vw] min-w-32 w-max overflow-hidden rounded-lg bg-popover p-0 text-sm text-popover-foreground shadow-floating no-focus-ring",
        "data-[side=bottom]:origin-top data-[side=left]:origin-right data-[side=right]:origin-left data-[side=top]:origin-bottom data-[state=closed]:hidden data-[state=open]:animate-zoom",
        className,
      )}
      sideOffset={4}
      {...props}
    />
  );

  if (portal) {
    return (
      <DropdownMenuPrimitive.Portal>{content}</DropdownMenuPrimitive.Portal>
    );
  }

  return content;
}

export function DropdownMenuItem({
  className,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Item> &
  VariantProps<typeof dropdownMenuItemVariants>) {
  return (
    <DropdownMenuPrimitive.Item
      className={cn(dropdownMenuItemVariants(), className)}
      {...props}
    />
  );
}

export function DropdownMenuCheckboxItem({
  children,
  className,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.CheckboxItem>) {
  return (
    <DropdownMenuPrimitive.CheckboxItem
      className={cn(
        "relative flex items-center gap-2 rounded-sm py-1.5 pr-8 pl-2 no-focus-ring transition-bg-ease select-none focus:bg-accent focus:text-accent-foreground data-disabled:pointer-events-none data-disabled:opacity-50 [&_svg]:size-4",
        // NOTE: Do NOT use %/calc-based widths here for the same reason as
        // dropdownMenuItemVariants: it prevents shrink-to-fit content sizing.
        // IMPORTANT: Don't use `px-*` here, it would override `pr-8` above and
        // cause the label to overlap the right-side check indicator.
        "mx-1 h-[28px] cursor-pointer data-[state=highlighted]:bg-accent data-[state=highlighted]:text-accent-foreground",
        className,
      )}
      {...props}
    >
      <span className="absolute right-2 flex size-3.5 items-center justify-center">
        <DropdownMenuPrimitive.ItemIndicator>
          <CheckIcon />
        </DropdownMenuPrimitive.ItemIndicator>
      </span>
      {children}
    </DropdownMenuPrimitive.CheckboxItem>
  );
}

export function DropdownMenuRadioItem({
  children,
  className,
  hideIcon,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.RadioItem> & {
  hideIcon?: boolean;
}) {
  return (
    <DropdownMenuPrimitive.RadioItem
      className={cn(
        "relative flex items-center rounded-sm pr-2 pl-8 no-focus-ring transition-bg-ease select-none focus:bg-accent focus:text-accent-foreground data-disabled:pointer-events-none data-disabled:opacity-50",
        // NOTE: Do NOT use %/calc-based widths here for the same reason as
        // dropdownMenuItemVariants: it prevents shrink-to-fit content sizing.
        // IMPORTANT: Don't use `px-*` here, it would override `pl-8` above and
        // misalign the radio indicator.
        "mx-1 h-[28px] cursor-pointer gap-2 data-[state=highlighted]:bg-accent data-[state=highlighted]:text-accent-foreground [&_svg]:size-4",
        className,
      )}
      {...props}
    >
      {!hideIcon && (
        <span className="absolute left-2 flex size-3.5 items-center justify-center">
          <DropdownMenuPrimitive.ItemIndicator>
            <CheckIcon />
          </DropdownMenuPrimitive.ItemIndicator>
        </span>
      )}
      {children}
    </DropdownMenuPrimitive.RadioItem>
  );
}

export function DropdownMenuLabel({
  className,
  inset,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Label> & {
  inset?: boolean;
}) {
  return (
    <DropdownMenuPrimitive.Label
      className={cn(dropdownMenuLabelVariants({inset}), className)}
      {...props}
    />
  );
}

export function DropdownMenuSeparator({
  className,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Separator>) {
  return (
    <DropdownMenuPrimitive.Separator
      className={cn("-mx-1 my-1 h-px bg-muted", className)}
      {...props}
    />
  );
}

export function DropdownMenuShortcut({
  className,
  ...props
}: React.ComponentProps<"span">) {
  return (
    <span
      className={cn("ml-auto text-xs tracking-widest opacity-60", className)}
      {...props}
    />
  );
}

export function useOpenState() {
  const [open, setOpen] = React.useState(false);

  const onOpenChange = React.useCallback(
    (_value = !open) => {
      setOpen(_value);
    },
    [open],
  );

  return {
    open,
    onOpenChange,
  };
}

import {actionTypesToEvents, registerCardComponent} from "@pihanga2/core";

import {DROP_DOWN_MENU_ACTION, DROP_DOWN_MENU_CARD} from "./drop-down.types";
import {Component} from "./drop-down.component";

export * from "./drop-down.types";

registerCardComponent({
  name: DROP_DOWN_MENU_CARD,
  component: Component,
  events: actionTypesToEvents(DROP_DOWN_MENU_ACTION),
});
